-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 17: Como Implantar a Governança de TI — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('9f38f096-6d53-558f-977e-bb30ac4d34f9', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'Qual apoio é essencial para iniciar um programa de governança de TI?', '["Patrocínio da alta administração.","Somente entusiasmo do fornecedor.","Apenas compra de ferramenta.","Exclusivamente autorização informal de um usuário.","Somente criação de um logotipo."]'::jsonb, 0, 'O patrocínio sustenta liderança, legitimidade e recursos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d87794f3-b6de-5d17-a50c-182c5f09d50a', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Médio', 'Definir o foco inicial do programa exige principalmente:', '["Contar certificações individuais.","Priorizar apenas ferramentas disponíveis.","Analisar estratégia, necessidades e vulnerabilidades do negócio.","Copiar todos os processos de outra empresa.","Escolher somente o modelo mais famoso."]'::jsonb, 2, 'O foco deve refletir o que é mais relevante para a organização.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('66238b3a-bd55-5733-8364-8e5c29c4b538', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Médio', 'Se a continuidade é a principal necessidade do negócio, qual foco inicial é coerente?', '["Apenas troca de linguagem.","Somente identidade visual dos sistemas.","Exclusivamente expansão comercial.","Segurança e processos de continuidade dos serviços.","Somente redes sociais."]'::jsonb, 3, 'A prioridade decorre do impacto das interrupções no negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d07246bd-c48d-5ab9-92da-cca25c6ae9b4', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Médio', 'Antes de distribuir atividades do programa, é necessário definir:', '["Apenas a data da festa de lançamento.","Exclusivamente o fornecedor de treinamento.","Somente o layout das salas.","Papéis, estrutura e relacionamentos com os interessados.","Somente nomes das ferramentas."]'::jsonb, 3, 'Responsabilidades claras tornam possível coordenar a implantação.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f85415e8-91c9-5017-a8b5-a5a7377e339f', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Médio', 'Avaliar processos-foco antes de planejar melhorias permite:', '["Substituir o plano de recursos.","Dispensar metas.","Garantir automaticamente o nível máximo.","Conhecer a situação atual e identificar lacunas.","Eliminar a necessidade de priorização."]'::jsonb, 3, 'O diagnóstico ajuda a selecionar ações urgentes e evoluções posteriores.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01f56875-bb73-59c6-a716-5236269e2b27', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Médio', 'Por que conhecer o desempenho atual antes de estabelecer metas?', '["A avaliação inicial elimina riscos.","Metas só podem repetir o valor atual.","É necessário ter uma referência para definir e avaliar melhorias.","O desempenho nunca muda.","Indicadores substituem o orçamento."]'::jsonb, 2, 'A linha de base permite dimensionar a evolução pretendida.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('301c6c7f-5645-5777-8b0c-7b5ec9c91c04', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Fácil', 'O roadmap de implantação deve explicitar:', '["Sequência, dependências e horizonte temporal das ações.","Apenas inventário de hardware.","Somente nomes de cargos.","Somente resultados financeiros passados.","Exclusivamente contatos de fornecedores."]'::jsonb, 0, 'O roteiro organiza a evolução das capacidades e dos benefícios.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2e661a46-4324-539c-8419-f6fd62864a1d', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'Ganhos rápidos devem ser escolhidos principalmente por:', '["Relevância e viabilidade frente às prioridades identificadas.","Facilidade de divulgar sem entregar.","Possibilidade de evitar qualquer medição.","Preferência individual do gerente.","Quantidade de documentos produzidos."]'::jsonb, 0, 'Resultados iniciais úteis reforçam a credibilidade do programa.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f5e03b0f-bd9f-51ad-ad85-3daba6638654', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Médio', 'O plano do programa deve incluir, entre outros itens:', '["Somente certificados da equipe.","Escopo, recursos, orçamento, riscos, benefícios e comunicação.","Somente a lista de ferramentas.","Apenas o nome do patrocinador.","Exclusivamente datas de reuniões."]'::jsonb, 1, 'O plano precisa permitir execução, controle e avaliação dos resultados.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b02593f3-e573-5d3e-ae4a-4cda07b824ed', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Médio', 'Por que estabelecer parcerias com auditoria, riscos e compliance?', '["Para dispensar participação do CIO.","Para transferir a elas todo o suporte.","Elas ajudam a identificar vulnerabilidades e acompanhar resultados.","Para substituir a estratégia por auditoria.","Para eliminar a gestão de projetos."]'::jsonb, 2, 'Essas áreas fornecem perspectivas relevantes para a evolução da governança.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('01e76253-7df2-5c1a-9175-71c927891497', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Médio', 'A aprovação do programa pela alta administração permite principalmente:', '["Dispensar todo acompanhamento.","Alterar qualquer política sem controle.","Eliminar a gestão de riscos.","Garantir sucesso automático.","Executar os recursos e o orçamento aprovados."]'::jsonb, 4, 'A autorização viabiliza a mobilização dos recursos necessários.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8f69151a-2514-570d-aba5-544da7239f44', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Médio', 'Um plano de mudança cultural deve começar por conhecer:', '["Somente fornecedores de software.","Exclusivamente quantidade de equipamentos.","Apenas salários individuais.","Cultura atual, cultura desejada e lacunas.","Somente organograma externo."]'::jsonb, 3, 'As iniciativas devem tratar a distância entre comportamentos atuais e desejados.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('251c3e44-6315-5c48-a162-7f808c335f55', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Médio', 'Capacitar pessoas durante a implantação atende a qual necessidade?', '["Apenas aumentar o número de certificados.","Desenvolver competências para novos processos e sistemas.","Dispensar comunicação.","Eliminar a necessidade de apoio posterior.","Substituir o patrocínio executivo."]'::jsonb, 1, 'A adoção exige condições para executar o novo trabalho.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f00506db-630b-5274-bb2b-5f130b41dd72', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Médio', 'A liderança precisa dar exemplo na mudança porque:', '["A mudança depende apenas de discursos.","Treinamento de equipes é desnecessário.","Somente líderes usam os processos.","Valores individuais nunca afetam práticas.","Seu comportamento influencia a cultura coletiva."]'::jsonb, 4, 'Comportamentos, símbolos e sistemas precisam ser coerentes com a transformação.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('84f9b8ce-6b9b-5100-960b-ba89e83bc63f', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Difícil', 'O projeto entregou documentos, mas ninguém usa os processos. Qual resultado precisa ser avaliado?', '["Apenas custo do treinamento.","Adoção efetiva e benefícios alcançados.","Somente quantidade de páginas.","Exclusivamente número de reuniões.","Somente prazo de entrega do manual."]'::jsonb, 1, 'Entregáveis formais não garantem mudança operacional ou valor.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('599ea70f-3b29-5eec-93ee-6b32968cd439', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Durante a execução, o monitoramento deve acompanhar:', '["Exclusivamente quantidade de consultores.","Progresso, qualidade, riscos e adoção.","Somente presença nas reuniões.","Somente horas contratadas.","Apenas publicidade do programa."]'::jsonb, 1, 'O acompanhamento precisa avaliar execução e condições de sucesso.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('337e1e89-b76a-5cce-8008-b88c0366301c', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Médio', 'Comunicar valor ao negócio exige evidenciar principalmente:', '["Exclusivamente certificados adquiridos.","Somente quantidade de ferramentas.","Resultados relevantes, como disponibilidade e atendimento ao crescimento.","Apenas total de políticas publicadas.","Somente número de diagramas."]'::jsonb, 2, 'O valor deve ser expresso em termos compreensíveis e úteis ao negócio.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b2765376-378f-5a79-86f2-dfd399e893a6', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Médio', 'Após concluir os primeiros projetos, qual atitude é coerente com o roteiro?', '["Avaliar resultados e planejar a evolução.","Parar de analisar a estratégia.","Declarar a governança definitivamente encerrada.","Suspender todos os indicadores.","Eliminar responsáveis pelos processos."]'::jsonb, 0, 'A governança precisa continuar evoluindo com a organização.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.1, páginas 618–631 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('cafe8025-32d7-5ab6-89b2-977f3f36e915', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Fácil', 'Qual fator crítico é destacado para o sucesso da implantação?', '["Exclusividade da equipe técnica.","Escolha obrigatória de um único fornecedor.","Implantação sem comunicação.","Ausência de patrocinador.","Envolvimento dos executivos da organização."]'::jsonb, 4, 'Mudanças em TI afetam outras áreas e precisam de compromisso executivo.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.2, páginas 631–632 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1d8374e5-fac8-5f9c-a827-80c93d82d425', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Difícil', 'Um programa tem ótima ferramenta, mas não tem liderança nem recursos comprometidos. Qual avaliação é adequada?', '["A ferramenta garante sucesso suficiente.","A ausência de liderança aumenta a maturidade.","Os recursos só importam após a conclusão.","O programa já atende todos os fatores de sucesso.","Faltam condições organizacionais críticas para sua implantação."]'::jsonb, 4, 'Tecnologia não substitui patrocínio, recursos e participação da organização.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 17, seção 17.2, páginas 631–632 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
